 1	const {test} = require('node:test');
 2	const assert = require('node:assert/strict');
 3	const vm = require('node:vm');
 4	const fs = require('node:fs');
 5	const path = require('node:path');
 6	const script = fs.readFileSync(path.join(__dirname, '../services/docs_auth.js'), 'utf8');
 7	
 8	function setup(clientId = 'test-client') {
 9	  const elements = {};
10	  const state = {authorized: null, callbacks: [], timers: []};
11	  const context = vm.createContext({
12	    googleAuthConfig: {clientId},
13	    document: {getElementById(id) {
14	      return elements[id] ??= {addEventListener(event, callback) {this[event] = callback;}};
15	    }},
16	    window: {location: {origin: 'http://localhost:8000'}},
17	    ui: {
18	      authSelectors: {authorized() {return {get() {return state.authorized;}};}},
19	      authActions: {logout() {state.authorized = null;}},
20	      preauthorizeApiKey(scheme, token) {state.authorized = {scheme, token};},
21	    },
22	    google: {accounts: {oauth2: {
23	      initTokenClient(config) {
24	        state.callbacks.push(config);
25	        return {requestAccessToken() {}};
26	      },
27	      hasGrantedAllScopes(response, scope) {return response.scope === scope;},
28	    }}},
29	    setTimeout(callback) {state.timers.push(callback); return state.timers.length;},
30	    clearTimeout() {},
31	  });
32	  vm.runInContext(script, context);
33	  context.googleIdentityReady();
34	  return {elements, state};
35	}
36	
37	test('Google grant authorizes Swagger; expiry clears access', () => {
38	  const {elements, state} = setup();
39	  elements['connect-gmail'].click();
40	  const config = state.callbacks[0];
41	  assert.equal(config.scope, 'https://www.googleapis.com/auth/gmail.readonly');
42	  config.callback({access_token: 'fake-token', scope: config.scope, expires_in: 3600});
43	  assert.deepEqual(state.authorized, {scheme: 'GoogleAccessToken', token: 'fake-token'});
44	  state.timers[0]();
45	  assert.equal(state.authorized, null);
46	  assert.match(elements['google-status'].textContent, /expired/);
47	});
48	
49	test('missing client ID disables connection', () => {
50	  const {elements} = setup('');
51	  assert.equal(elements['connect-gmail'].disabled, true);
52	  assert.match(elements['google-status'].textContent, /not configured/);
53	});
54	
55	test('denied scope never authorizes Swagger', () => {
56	  const {elements, state} = setup();
57	  elements['connect-gmail'].click();
58	  state.callbacks[0].callback({access_token: 'fake-token', scope: '', expires_in: 3600});
59	  assert.equal(state.authorized, null);
60	  assert.match(elements['google-status'].textContent, /not granted/);
61	});
62	
63	test('disconnect invalidates pending Google callbacks', () => {
64	  const {elements, state} = setup();
65	  elements['connect-calendar'].click();
66	  const config = state.callbacks[0];
67	  elements['disconnect-google'].click();
68	  config.callback({access_token: 'fake-token', scope: config.scope, expires_in: 3600});
69	  assert.equal(state.authorized, null);
70	});
71	
72	test('closed popup gives a retry message', () => {
73	  const {elements, state} = setup();
74	  elements['connect-gmail'].click();
75	  state.callbacks[0].error_callback({type: 'popup_closed'});
76	  assert.equal(state.authorized, null);
77	  assert.match(elements['google-status'].textContent, /closed or blocked/);
78	});

